//! Scan result types (PLAN.md section 3). TS bindings are generated by `ts-rs`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct VolumeInfo {
    #[ts(type = "number")]
    pub total: u64,
    #[ts(type = "number")]
    pub available: u64,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct NodeFlags {
    pub inaccessible: bool,
    pub symlink: bool,
    pub mount: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct FileLeaf {
    pub name: String,
    #[ts(type = "number")]
    pub size: u64,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct DirNode {
    pub id: u32,
    pub parent: Option<u32>,
    pub name: String,
    /// Allocated size (`st_blocks * 512`), aggregated over the subtree.
    #[ts(type = "number")]
    pub size: u64,
    #[ts(type = "number")]
    pub logical_size: u64,
    #[ts(type = "number")]
    pub file_count: u64,
    pub children: Vec<u32>,
    pub top_files: Vec<FileLeaf>,
    pub flags: NodeFlags,
    /// Resolved in Phase 3; empty after scanning.
    pub category: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct SnapshotMeta {
    pub id: String,
    pub root: String,
    #[ts(type = "number")]
    pub scanned_at: i64,
    #[ts(type = "number")]
    pub duration_ms: u64,
    pub volume: VolumeInfo,
    #[ts(type = "number")]
    pub scanned_size: u64,
    pub inaccessible_count: u32,
}

/// Arena of directories; index = `DirNode::id`, root is index 0.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Snapshot {
    pub meta: SnapshotMeta,
    pub nodes: Vec<DirNode>,
}

#[derive(Debug, Clone, Serialize, TS)]
#[serde(tag = "event", content = "data", rename_all = "camelCase")]
#[ts(export)]
pub enum ScanEvent {
    Progress {
        #[ts(type = "number")]
        files: u64,
        #[ts(type = "number")]
        bytes: u64,
        current: String,
    },
    Finished {
        meta: SnapshotMeta,
    },
    Failed {
        message: String,
    },
}

const TOP_FILES: usize = 20;

/// Builds the arena from a depth-first, parent-before-children stream of entries.
///
/// Ids are assigned in visit order, so a child's id is always greater than its
/// parent's. That lets `finish` aggregate sizes with one reverse pass.
#[derive(Default)]
pub struct TreeBuilder {
    nodes: Vec<DirNode>,
    /// `stack[d]` is the id of the directory currently open at depth `d`.
    stack: Vec<u32>,
    hardlinks: super::hardlinks::HardLinks,
}

impl TreeBuilder {
    /// Open a directory at `depth` (0 = scan root). `own_size` is its own allocated size.
    pub fn push_dir(&mut self, depth: usize, name: String, own_size: u64, flags: NodeFlags) -> u32 {
        let id = self.nodes.len() as u32;
        let parent = depth.checked_sub(1).map(|d| self.stack[d]);
        self.stack.truncate(depth);
        self.stack.push(id);
        if let Some(p) = parent {
            self.nodes[p as usize].children.push(id);
        }
        self.nodes.push(DirNode {
            id,
            parent,
            name,
            size: own_size,
            logical_size: 0,
            file_count: 0,
            children: Vec::new(),
            top_files: Vec::new(),
            flags,
            category: String::new(),
        });
        id
    }

    /// Mark the directory at `depth` as unreadable.
    pub fn mark_inaccessible(&mut self, depth: usize) {
        let id = self.stack[depth];
        self.nodes[id as usize].flags.inaccessible = true;
    }

    /// Add a file whose parent is the directory open at `depth - 1`.
    ///
    /// `link` is `(dev, ino)` for files with more than one hard link: only the first
    /// sighting is counted. Callers must feed entries in sorted, parent-first order.
    pub fn add_file(
        &mut self,
        depth: usize,
        name: &str,
        size: u64,
        logical: u64,
        link: Option<(u64, u64)>,
    ) {
        if let Some((dev, ino)) = link
            && !self.hardlinks.first_sighting(dev, ino)
        {
            return;
        }
        let node = &mut self.nodes[self.stack[depth - 1] as usize];
        node.size += size;
        node.logical_size += logical;
        node.file_count += 1;
        // Keep the 20 largest (ties broken by name) without allocating names for the rest.
        if node.top_files.len() < TOP_FILES {
            node.top_files.push(FileLeaf {
                name: name.to_owned(),
                size,
            });
        } else if let Some((i, min)) = node
            .top_files
            .iter()
            .enumerate()
            .min_by(|(_, a), (_, b)| a.size.cmp(&b.size).then_with(|| b.name.cmp(&a.name)))
            && (size > min.size || (size == min.size && name < min.name.as_str()))
        {
            node.top_files[i] = FileLeaf {
                name: name.to_owned(),
                size,
            };
        }
    }

    pub fn finish(mut self) -> Vec<DirNode> {
        for node in &mut self.nodes {
            trim_top(&mut node.top_files);
        }
        // Children have larger ids than parents: one reverse pass aggregates the subtree.
        for i in (1..self.nodes.len()).rev() {
            let (size, logical, files) = {
                let n = &self.nodes[i];
                (n.size, n.logical_size, n.file_count)
            };
            let p = self.nodes[i].parent.expect("non-root has parent") as usize;
            let parent = &mut self.nodes[p];
            parent.size += size;
            parent.logical_size += logical;
            parent.file_count += files;
        }
        let sizes: Vec<u64> = self.nodes.iter().map(|n| n.size).collect();
        for node in &mut self.nodes {
            node.children
                .sort_by_key(|&c| std::cmp::Reverse(sizes[c as usize]));
        }
        self.nodes
    }
}

fn trim_top(files: &mut Vec<FileLeaf>) {
    files.sort_by(|a, b| b.size.cmp(&a.size).then_with(|| a.name.cmp(&b.name)));
    files.truncate(TOP_FILES);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn aggregates_bottom_up_and_orders_children() {
        let mut b = TreeBuilder::default();
        b.push_dir(0, "root".into(), 0, NodeFlags::default());
        b.push_dir(1, "small".into(), 0, NodeFlags::default());
        b.add_file(2, "f", 100, 90, None);
        b.push_dir(1, "big".into(), 0, NodeFlags::default());
        b.add_file(2, "g", 500, 400, None);
        b.add_file(1, "top", 7, 7, None);
        let n = b.finish();
        assert_eq!(
            (n[0].size, n[0].logical_size, n[0].file_count),
            (607, 497, 3)
        );
        assert_eq!(n[0].children, vec![2, 1]); // big before small
        assert_eq!(n[2].parent, Some(0));
    }

    #[test]
    fn keeps_only_the_largest_twenty_files() {
        let mut b = TreeBuilder::default();
        b.push_dir(0, "root".into(), 0, NodeFlags::default());
        for i in 0..100u64 {
            b.add_file(1, &format!("f{i:03}"), i, i, None);
        }
        let n = b.finish();
        assert_eq!(n[0].top_files.len(), 20);
        assert_eq!(n[0].top_files[0].size, 99);
        assert_eq!(n[0].top_files[19].size, 80);
        assert_eq!(n[0].file_count, 100);
    }

    #[test]
    fn linked_file_counted_once_at_first_sighting() {
        let mut b = TreeBuilder::default();
        b.push_dir(0, "root".into(), 0, NodeFlags::default());
        b.push_dir(1, "a".into(), 0, NodeFlags::default());
        b.add_file(2, "x", 4096, 10, Some((1, 9)));
        b.push_dir(1, "b".into(), 0, NodeFlags::default());
        b.add_file(2, "y", 4096, 10, Some((1, 9)));
        let n = b.finish();
        assert_eq!((n[0].size, n[0].file_count), (4096, 1));
        assert_eq!(n[1].size, 4096);
        assert_eq!(n[2].size, 0);
    }

    #[test]
    fn top_file_ties_break_by_name() {
        let mut b = TreeBuilder::default();
        b.push_dir(0, "root".into(), 0, NodeFlags::default());
        for i in (0..25).rev() {
            b.add_file(1, &format!("f{i:02}"), 5, 5, None);
        }
        let n = b.finish();
        let names: Vec<_> = n[0].top_files.iter().map(|f| f.name.as_str()).collect();
        assert_eq!(names.first(), Some(&"f00"));
        assert_eq!(names.last(), Some(&"f19"));
    }
}
